VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_rdp_222'), 'Five login attempts in one minute pass and remaining counts down', '{"limit":5,"windowSeconds":60,"requests":[{"at":0,"key":"ip:203.0.113.7"},{"at":5000,"key":"ip:203.0.113.7"},{"at":10000,"key":"ip:203.0.113.7"},{"at":15000,"key":"ip:203.0.113.7"},{"at":20000,"key":"ip:203.0.113.7"}]}', '"0.000s ip:203.0.113.7 | fixed: allowed, 4 left | sliding: allowed, 4 left\n5.000s ip:203.0.113.7 | fixed: allowed, 3 left | sliding: allowed, 3 left\n10.000s ip:203.0.113.7 | fixed: allowed, 2 left | sliding: allowed, 2 left\n15.000s ip:203.0.113.7 | fixed: allowed, 1 left | sliding: allowed, 1 left\n20.000s ip:203.0.113.7 | fixed: allowed, 0 left | sliding: allowed, 0 left\ntwo windows later: fixed 0 keys, sliding 0 keys"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_rdp_222'), 'The sixth attempt is denied with a retry-after; later attempts pass again', '{"limit":5,"windowSeconds":60,"requests":[{"at":0,"key":"ip:203.0.113.7"},{"at":5000,"key":"ip:203.0.113.7"},{"at":10000,"key":"ip:203.0.113.7"},{"at":15000,"key":"ip:203.0.113.7"},{"at":20000,"key":"ip:203.0.113.7"},{"at":30000,"key":"ip:203.0.113.7"},{"at":60000,"key":"ip:203.0.113.7"},{"at":71000,"key":"ip:203.0.113.7"},{"at":72000,"key":"ip:203.0.113.7"}]}', '"0.000s ip:203.0.113.7 | fixed: allowed, 4 left | sliding: allowed, 4 left\n5.000s ip:203.0.113.7 | fixed: allowed, 3 left | sliding: allowed, 3 left\n10.000s ip:203.0.113.7 | fixed: allowed, 2 left | sliding: allowed, 2 left\n15.000s ip:203.0.113.7 | fixed: allowed, 1 left | sliding: allowed, 1 left\n20.000s ip:203.0.113.7 | fixed: allowed, 0 left | sliding: allowed, 0 left\n30.000s ip:203.0.113.7 | fixed: denied, retry in 30s | sliding: denied, retry in 42s\n60.000s ip:203.0.113.7 | fixed: allowed, 4 left | sliding: denied, retry in 12s\n71.000s ip:203.0.113.7 | fixed: allowed, 3 left | sliding: denied, retry in 1s\n72.000s ip:203.0.113.7 | fixed: allowed, 2 left | sliding: allowed, 0 left\ntwo windows later: fixed 0 keys, sliding 0 keys"', 3, true, false, 2),
