INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_rdp_312'), 'All-time and weekly top N: equal scores keep Redis order and ranks are ordinal', '{"ops":[{"op":"clock","at":"2026-10-28T18:00:00Z"},{"op":"score","learnerId":"u_1","points":50,"at":"2026-10-26T09:12:00Z"},{"op":"score","learnerId":"u_3","points":90,"at":"2026-10-26T11:40:00Z"},{"op":"score","learnerId":"u_7","points":120,"at":"2026-10-27T08:05:00Z"},{"op":"score","learnerId":"u_1","points":40,"at":"2026-10-27T19:30:00Z"},{"op":"score","learnerId":"u_5","points":30,"at":"2026-10-28T07:00:00Z"},{"op":"score","learnerId":"u_2","points":90,"at":"2026-10-28T17:59:00Z"},{"op":"top","board":"all","n":3},{"op":"top","board":"2026-10-28T12:00:00Z","n":10},{"op":"rank","board":"all","learnerId":"u_2"},{"op":"rank","board":"2026-10-28T12:00:00Z","learnerId":"u_1"},{"op":"rank","board":"all","learnerId":"u_7"}]}', '"score \"u_1\" 50 \"2026-10-26T09:12:00Z\" -> recorded\nscore \"u_3\" 90 \"2026-10-26T11:40:00Z\" -> recorded\nscore \"u_7\" 120 \"2026-10-27T08:05:00Z\" -> recorded\nscore \"u_1\" 40 \"2026-10-27T19:30:00Z\" -> recorded\nscore \"u_5\" 30 \"2026-10-28T07:00:00Z\" -> recorded\nscore \"u_2\" 90 \"2026-10-28T17:59:00Z\" -> recorded\ntop lb:all 3: 1. u_7 120 | 2. u_3 90 | 3. u_2 90\ntop lb:week:2026-W44 10: 1. u_7 120 | 2. u_3 90 | 3. u_2 90 | 4. u_1 90 | 5. u_5 30\nrank lb:all u_2: #3 with 90; around: 1. u_7 120 | 2. u_3 90 | 3. u_2 90 | 4. u_1 90 | 5. u_5 30\nrank lb:week:2026-W44 u_1: #4 with 90; around: 2. u_3 90 | 3. u_2 90 | 4. u_1 90 | 5. u_5 30\nrank lb:all u_7: #1 with 120; around: 1. u_7 120 | 2. u_3 90 | 3. u_2 90"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_rdp_312'), 'Weekly keys: Sunday night and Monday morning, two-digit weeks and the TTL to retention end', '{"ops":[{"op":"clock","at":"2026-01-05T08:00:00Z"},{"op":"score","learnerId":"u_2","points":10,"at":"2026-01-05T07:59:30Z"},{"op":"ttl","board":"2026-01-05T07:59:30Z"},{"op":"clock","at":"2026-03-08T23:59:59Z"},{"op":"score","learnerId":"u_4","points":30,"at":"2026-03-08T23:59:59Z"},{"op":"clock","at":"2026-03-09T00:00:00Z"},{"op":"score","learnerId":"u_4","points":20,"at":"2026-03-09T00:00:00Z"},{"op":"score","learnerId":"u_9","points":25,"at":"2026-03-08T22:00:00Z"},{"op":"top","board":"2026-03-08T12:00:00Z","n":5},{"op":"top","board":"2026-03-09T12:00:00Z","n":5},{"op":"ttl","board":"2026-03-08T12:00:00Z"},{"op":"ttl","board":"2026-03-09T12:00:00Z"},{"op":"top","board":"all","n":5}]}', '"score \"u_2\" 10 \"2026-01-05T07:59:30Z\" -> recorded\nttl lb:week:2026-W02: 1180800\nscore \"u_4\" 30 \"2026-03-08T23:59:59Z\" -> recorded\nscore \"u_4\" 20 \"2026-03-09T00:00:00Z\" -> recorded\nscore \"u_9\" 25 \"2026-03-08T22:00:00Z\" -> recorded\ntop lb:week:2026-W10 5: 1. u_4 30 | 2. u_9 25\ntop lb:week:2026-W11 5: 1. u_4 20\nttl lb:week:2026-W10: 604800\nttl lb:week:2026-W11: 1209600\ntop lb:all 5: 1. u_4 50 | 2. u_9 25 | 3. u_2 10"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_rdp_312'), 'The incident: the first, second and last learner get only neighbours that exist', '{"ops":[{"op":"clock","at":"2026-10-29T10:00:00Z"},{"op":"score","learnerId":"u_0815","points":640,"at":"2026-10-29T09:00:00Z"},{"op":"score","learnerId":"u_2040","points":610,"at":"2026-10-29T09:01:00Z"},{"op":"score","learnerId":"u_1001","points":580,"at":"2026-10-29T09:02:00Z"},{"op":"score","learnerId":"u_3310","points":420,"at":"2026-10-29T09:03:00Z"},{"op":"score","learnerId":"u_7781","points":300,"at":"2026-10-29T09:04:00Z"},{"op":"score","learnerId":"u_5120","points":120,"at":"2026-10-29T09:05:00Z"},{"op":"rank","board":"all","learnerId":"u_0815"},{"op":"rank","board":"all","learnerId":"u_2040"},{"op":"rank","board":"all","learnerId":"u_1001"},{"op":"rank","board":"all","learnerId":"u_7781"},{"op":"rank","board":"all","learnerId":"u_5120"}]}', '"score \"u_0815\" 640 \"2026-10-29T09:00:00Z\" -> recorded\nscore \"u_2040\" 610 \"2026-10-29T09:01:00Z\" -> recorded\nscore \"u_1001\" 580 \"2026-10-29T09:02:00Z\" -> recorded\nscore \"u_3310\" 420 \"2026-10-29T09:03:00Z\" -> recorded\nscore \"u_7781\" 300 \"2026-10-29T09:04:00Z\" -> recorded\nscore \"u_5120\" 120 \"2026-10-29T09:05:00Z\" -> recorded\nrank lb:all u_0815: #1 with 640; around: 1. u_0815 640 | 2. u_2040 610 | 3. u_1001 580\nrank lb:all u_2040: #2 with 610; around: 1. u_0815 640 | 2. u_2040 610 | 3. u_1001 580 | 4. u_3310 420\nrank lb:all u_1001: #3 with 580; around: 1. u_0815 640 | 2. u_2040 610 | 3. u_1001 580 | 4. u_3310 420 | 5. u_7781 300\nrank lb:all u_7781: #5 with 300; around: 3. u_1001 580 | 4. u_3310 420 | 5. u_7781 300 | 6. u_5120 120\nrank lb:all u_5120: #6 with 120; around: 4. u_3310 420 | 5. u_7781 300 | 6. u_5120 120"', 3, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_rdp_312'), 'ISO year at the turn of the year: 2020-W53, 2025-W01, 2026-W53 and 2027-W01', '{"ops":[{"op":"clock","at":"2021-01-03T23:00:00Z"},{"op":"score","learnerId":"u_11","points":15,"at":"2021-01-03T22:30:00Z"},{"op":"top","board":"2021-01-03T22:30:00Z","n":3},{"op":"clock","at":"2024-12-30T12:00:00Z"},{"op":"score","learnerId":"u_12","points":25,"at":"2024-12-30T11:00:00Z"},{"op":"top","board":"2024-12-30T11:00:00Z","n":3},{"op":"clock","at":"2026-12-31T12:00:00Z"},{"op":"score","learnerId":"u_13","points":35,"at":"2026-12-31T10:00:00Z"},{"op":"clock","at":"2027-01-01T09:00:00Z"},{"op":"score","learnerId":"u_14","points":45,"at":"2027-01-01T08:00:00Z"},{"op":"top","board":"2026-12-31T10:00:00Z","n":3},{"op":"ttl","board":"2027-01-01T08:00:00Z"},{"op":"clock","at":"2027-01-04T00:00:00Z"},{"op":"score","learnerId":"u_15","points":55,"at":"2027-01-04T00:00:00Z"},{"op":"top","board":"2027-01-04T00:00:00Z","n":3},{"op":"top","board":"2027-01-03T23:59:59Z","n":3},{"op":"top","board":"all","n":10}]}', '"score \"u_11\" 15 \"2021-01-03T22:30:00Z\" -> recorded\ntop lb:week:2020-W53 3: 1. u_11 15\nscore \"u_12\" 25 \"2024-12-30T11:00:00Z\" -> recorded\ntop lb:week:2025-W01 3: 1. u_12 25\nscore \"u_13\" 35 \"2026-12-31T10:00:00Z\" -> recorded\nscore \"u_14\" 45 \"2027-01-01T08:00:00Z\" -> recorded\ntop lb:week:2026-W53 3: 1. u_14 45 | 2. u_13 35\nttl lb:week:2026-W53: 831600\nscore \"u_15\" 55 \"2027-01-04T00:00:00Z\" -> recorded\ntop lb:week:2027-W01 3: 1. u_15 55\ntop lb:week:2026-W53 3: 1. u_14 45 | 2. u_13 35\ntop lb:all 10: 1. u_15 55 | 2. u_14 45 | 3. u_13 35 | 4. u_12 25 | 5. u_11 15"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_rdp_312'), 'Late events, expired weeks, unknown learners and boards: null ranks and empty tops', '{"ops":[{"op":"clock","at":"2026-10-30T10:00:00Z"},{"op":"score","learnerId":"u_21","points":60,"at":"2026-10-30T09:00:00Z"},{"op":"score","learnerId":"u_22","points":80,"at":"2026-10-30T09:30:00Z"},{"op":"clock","at":"2026-11-08T23:59:59Z"},{"op":"score","learnerId":"u_23","points":70,"at":"2026-11-01T23:00:00Z"},{"op":"ttl","board":"2026-10-28T12:00:00Z"},{"op":"top","board":"2026-10-28T12:00:00Z","n":5},{"op":"clock","at":"2026-11-09T00:00:00Z"},{"op":"ttl","board":"2026-10-28T12:00:00Z"},{"op":"top","board":"2026-10-28T12:00:00Z","n":5},{"op":"score","learnerId":"u_21","points":100,"at":"2026-10-31T10:00:00Z"},{"op":"top","board":"2026-10-28T12:00:00Z","n":5},{"op":"ttl","board":"2026-10-28T12:00:00Z"},{"op":"rank","board":"2026-10-28T12:00:00Z","learnerId":"u_21"},{"op":"rank","board":"all","learnerId":"u_21"},{"op":"rank","board":"all","learnerId":"u_99"},{"op":"rank","board":"2026-11-11T10:00:00Z","learnerId":"u_22"},{"op":"top","board":"2026-11-11T10:00:00Z","n":3},{"op":"top","board":"all","n":5}]}', '"score \"u_21\" 60 \"2026-10-30T09:00:00Z\" -> recorded\nscore \"u_22\" 80 \"2026-10-30T09:30:00Z\" -> recorded\nscore \"u_23\" 70 \"2026-11-01T23:00:00Z\" -> recorded\nttl lb:week:2026-W44: 1\ntop lb:week:2026-W44 5: 1. u_22 80 | 2. u_23 70 | 3. u_21 60\nttl lb:week:2026-W44: -2\ntop lb:week:2026-W44 5: (empty)\nscore \"u_21\" 100 \"2026-10-31T10:00:00Z\" -> recorded\ntop lb:week:2026-W44 5: (empty)\nttl lb:week:2026-W44: -2\nrank lb:week:2026-W44 u_21: null\nrank lb:all u_21: #1 with 160; around: 1. u_21 160 | 2. u_22 80 | 3. u_23 70\nrank lb:all u_99: null\nrank lb:week:2026-W46 u_22: null\ntop lb:week:2026-W46 3: (empty)\ntop lb:all 5: 1. u_21 160 | 2. u_22 80 | 3. u_23 70"', 3, false, true, 5),
