-- challenge chal_quiz_rdp_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_rdp_321', (SELECT id FROM catalog.course WHERE public_id = 'redis-patterns'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'redis-patterns') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-rdp-3-2' AND is_deleted = false LIMIT 1), 'versioned-score-update-quiz', 'Is this update really newer?', 'Two pieces of evidence from the score consumer: a Lua script that compares versions, and a timeline of two workers that check before they write.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
