VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_rdp_322'), 'The incident: a late older total and a retried update after a newer total', '{"initial":{"board":[["u_2290",300],["u_1001",520],["u_0815",610]],"versions":[["u_2290",13],["u_1001",21],["u_0815",30]]},"updates":[{"learnerId":"u_2290","totalScore":340,"version":14},{"learnerId":"u_1001","totalScore":560,"version":22},{"learnerId":"u_2290","totalScore":300,"version":13},{"learnerId":"u_2290","totalScore":340,"version":14},{"learnerId":"u_2290","totalScore":380,"version":15},{"learnerId":"u_1001","totalScore":520,"version":21},{"learnerId":"u_0815","totalScore":640,"version":31}],"orders":6}', '"\"u_2290\" v14 total 340 -> applied\n\"u_1001\" v22 total 560 -> applied\n\"u_2290\" v13 total 300 -> stale\n\"u_2290\" v14 total 340 -> duplicate\n\"u_2290\" v15 total 380 -> applied\n\"u_1001\" v21 total 520 -> stale\n\"u_0815\" v31 total 640 -> applied\nboard (3): 1. u_0815 640 | 2. u_1001 560 | 3. u_2290 380\nversions: u_0815=31 u_1001=22 u_2290=15\nsame final board and versions in 6 of 6 other orders"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_rdp_322'), 'Leaving the board keeps the version, so an older total cannot bring the learner back', '{"initial":{"board":[["u_5",120],["u_6",90]],"versions":[["u_5",3],["u_6",2]]},"updates":[{"learnerId":"u_5","totalScore":null,"version":4},{"learnerId":"u_5","totalScore":120,"version":3},{"learnerId":"u_5","totalScore":100,"version":2},{"learnerId":"u_5","totalScore":null,"version":4},{"learnerId":"u_6","totalScore":95,"version":3},{"learnerId":"u_5","totalScore":150,"version":5},{"learnerId":"u_7","totalScore":40,"version":1},{"learnerId":"u_7","totalScore":40,"version":1}],"orders":6}', '"\"u_5\" v4 total null -> applied\n\"u_5\" v3 total 120 -> stale\n\"u_5\" v2 total 100 -> stale\n\"u_5\" v4 total null -> duplicate\n\"u_6\" v3 total 95 -> applied\n\"u_5\" v5 total 150 -> applied\n\"u_7\" v1 total 40 -> applied\n\"u_7\" v1 total 40 -> duplicate\nboard (3): 1. u_5 150 | 2. u_6 95 | 3. u_7 40\nversions: u_5=5 u_6=3 u_7=1\nsame final board and versions in 6 of 6 other orders"', 3, true, false, 2),
