VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_rdp_412'), 'The incident: v17 redelivered after a restart must not overwrite v18', '{"trace":true,"steps":[{"deliver":{"eventId":"evt_a91","userId":"u_2041","total":1180,"version":16}},{"deliver":{"eventId":"evt_b07","userId":"u_2041","total":1240,"version":17}},{"restart":true},{"deliver":{"eventId":"evt_c55","userId":"u_2041","total":1310,"version":18}},{"deliver":{"eventId":"evt_b07","userId":"u_2041","total":1240,"version":17}}]}', '"1 evt_a91 u_2041 v16 total=1180 -> applied, ZSCORE 1180\n2 evt_b07 u_2041 v17 total=1240 -> applied, ZSCORE 1240\n3 restart: new consumer, same Redis\n4 evt_c55 u_2041 v18 total=1310 -> applied, ZSCORE 1310\n5 evt_b07 u_2041 v17 total=1240 -> duplicate, ZSCORE 1310\napplied 3, duplicate 1, stale 0, invalid 0\ntop: u_2041 1310\ndrift vs PostgreSQL: none\nseen markers: 3"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_rdp_412'), 'Two consumers reorder u_3307: v10 arrives before v9', '{"trace":true,"steps":[{"deliver":{"eventId":"evt_d12","userId":"u_1187","total":760,"version":4}},{"deliver":{"eventId":"evt_e40","userId":"u_3307","total":1025,"version":10}},{"deliver":{"eventId":"evt_e31","userId":"u_3307","total":990,"version":9}},{"deliver":{"eventId":"evt_d13","userId":"u_1187","total":905,"version":5}}]}', '"1 evt_d12 u_1187 v4 total=760 -> applied, ZSCORE 760\n2 evt_e40 u_3307 v10 total=1025 -> applied, ZSCORE 1025\n3 evt_e31 u_3307 v9 total=990 -> stale, ZSCORE 1025\n4 evt_d13 u_1187 v5 total=905 -> applied, ZSCORE 905\napplied 3, duplicate 0, stale 1, invalid 0\ntop: u_3307 1025, u_1187 905\ndrift vs PostgreSQL: none\nseen markers: 4"', 3, true, false, 2),
