-- challenge chal_quiz_rdp_431 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_rdp_431', (SELECT id FROM catalog.course WHERE public_id = 'redis-patterns'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'redis-patterns') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-rdp-4-3' AND is_deleted = false LIMIT 1), 'operating-redis-memory-eviction-persistence', 'Operating Redis: memory, eviction & persistence', 'Three statements on the shared Redis instance of CodeDev after learners were logged out and logins started to fail: what volatile-lru evicts, what allkeys-lru would do to sessions, and what AOF with everysec does and does not protect.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_rdp_431');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_rdp_431');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_rdp_431'), 'One Redis instance holds sessions, rate-limit counters, the leaderboard and the catalog cache.
$ redis-cli CONFIG GET maxmemory-policy
maxmemory-policy volatile-lru
$ redis-cli INFO keyspace
db0:keys=2140332,expires=61204,avg_ttl=402113
$ redis-cli --scan --pattern ''catalog:search:*'' --count 1000 | head -3 | xargs -n1 redis-cli TTL
(integer) -1
(integer) -1
(integer) -1
$ redis-cli INFO stats | grep evicted_keys
evicted_keys:48211

Statement: "Because the policy is volatile-lru, Redis makes room by evicting the least recently used catalog:search keys, so the sessions are safe."', 'single_choice'::question_type, 'False. volatile-lru only chooses among keys that have an expiry set. The catalog:search keys have no TTL (TTL returns -1), so they are never candidates; the keys that do have one are the sessions, the rate-limit counters and other short-lived keys, about 61,000 of 2.1 million. Those are what the 48,211 evictions removed, which is why learners were logged out. When no key with a TTL is left to evict, volatile-* behaves like noeviction and writes fail with an OOM error. The misconception is that an LRU policy always evicts "the cache": it evicts what the policy lets it see, and cache keys written without a TTL are invisible to every volatile-* policy.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_rdp_431') AND order_index = 1)
    RETURNING id
)
